window.kbPageData["views/entry/k-90788618c5f1d8fb"] = {"key":"entry/k-90788618c5f1d8fb","state":{"route":"entry/k-90788618c5f1d8fb"},"node":{"id":"k-90788618c5f1d8fb","mode":"k","title":"环形跑道反向相遇的路程和","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["环形跑道反向而行时相邻两次相遇的路程和等于一圈"],"qs":["国考 2025 副省级 行测#68"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"两人沿同一环形跑道持续反向前进，从同一点出发到首次再次相遇，或从一次相遇到紧邻的下一次相遇，两人所跑路程之和等于一圈。","review":{"definition":"两人沿同一环形跑道持续反向前进，从同一点出发到首次再次相遇，或从一次相遇到紧邻的下一次相遇，两人所跑路程之和等于一圈。","explanation":"两人的相对位移以各自路程之和累积，合满一圈时再次相遇，中途加速也适用。设甲、乙最初每分钟分别跑2和1个长度单位，则3分钟共跑9个单位，即一圈长9个单位。第二次相遇前乙正好跑半圈，甲也跑半圈，以原速度跑4.5个单位需2.25分钟，即2分15秒。","references":[],"evidence":"又是一圈，而乙正好跑了半圈，则甲跑的路程也为半圈","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 副省级 行测#68":{"paper":"国考 2025 副省级 行测","n":68,"mod":"数量关系","src":["ffe12c35a46d4df574ec.pdf",12],"asrc":["ff0b352b44d417525086.pdf",21],"card":"9d817aa16748706d56a815f3","links":[{"id":"k-90788618c5f1d8fb","role":"解题依据","why":"两人从相遇点反向出发，到下次相遇时合计跑一圈，据此确定甲在该时段的路程。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-90788618c5f1d8fb":[["国考 2025 副省级 行测#68"]]}};
